@startuml

class Aircraft {
  + Name : string
  + Type : string
  + YearOfManufacture : int
  + NextInspectionDate : date
}

class PassengerAircraft extends Aircraft {
  + SeatCount : int
}

class SeatCategory {
  + Designation : string
  + OffersEntertainment : boolean
  + SeatCount : int
}

class Flight {
  + FlightNumber : string
  + Date : date
}

class Passenger {
  + Name : string
  + PassportNumber : string
}

class Ticket {
  + TicketNumber : string
  + Price : float
  + UpgradeDesired : boolean
}

class Airline {
  + Name : string
}

class FlightAttendant {
  + Name : string
  + EmploymentDate : date
  + IsChiefStewardess : boolean
}

class Pilot {
  + Name : string
  + EmploymentDate : date
  + License : string
}

class Airport {
  + Name : string
  + Address : string
  + RunwayCount : int
}

Airline "1" -- "*" Aircraft : belongs to
Airline "1" -- "*" FlightAttendant : employs
Airline "1" -- "*" Pilot : employs

Aircraft "1" -- "*" Flight : performs
Aircraft "0..1" -- "1" Airport : home airport

Flight "1" -- "1" Airport : departs from
Flight "1" -- "1" Airport : arrives at
Flight "1" -- "1..*" FlightAttendant : staffed by
Flight "1" -- "1" Pilot : Captain
Flight "1" -- "1..2" Pilot : Co-pilots

Passenger "1" -- "*" Ticket : holds
Ticket "*" -- "1" Flight : for
Ticket "*" -- "1" SeatCategory : assigned to
Passenger "*" -- "*" Flight : participates in

PassengerAircraft "1" -- "*" SeatCategory : has
@enduml

